**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[5][5];
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            plik >> m[i][j];

    // a) Spirala ramki
    cout << "a) Spirala ramki:";
    for (int j = 0; j <= 4; j++) cout << " " << m[0][j];      // gorny wiersz
    for (int i = 1; i <= 4; i++) cout << " " << m[i][4];      // prawa kolumna
    for (int j = 3; j >= 0; j--) cout << " " << m[4][j];      // dolny wiersz
    for (int i = 3; i >= 1; i--) cout << " " << m[i][0];      // lewa kolumna
    cout << endl;

    // b) Suma ramki
    int sumR = 0, sumI = 0;
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++) {
            if (i == 0 || i == 4 || j == 0 || j == 4)
                sumR += m[i][j];
            else
                sumI += m[i][j];
        }
    cout << "b) Suma ramki: " << sumR << endl;
    cout << "c) Suma wewnetrznych: " << sumI << endl;
    return 0;
}
```

**Wyjasnienie**: Spiralne odczytanie ramki to 4 petle: gorny wiersz w prawo, prawa kolumna w dol, dolny wiersz w lewo, lewa kolumna w gore. Suma ramki i wnetrza — podwojna petla z warunkiem.

Weryfikacja:
- Spirala: 1,2,3,4,5 | 10,15,20 | 25,24,23,22 | 21,16,11,6 -> 16 elementow (ramka 5x5 ma 16)
- Suma ramki: 1+2+3+4+5+10+15+20+25+24+23+22+21+16+11+6 = 208
  Sprawdzenie: (1+2+3+4+5)+(10+15+20)+(25+24+23+22)+(21+16+11+6) = 15+45+94+54 = 208
- Suma wewnetrznych (3x3): 7+8+9+12+13+14+17+18+19 = 117
